-- ============================================================================
--  Business Automation Platform - baseline schema
--
--  Written in the SQL subset that is valid on both PostgreSQL and H2 running in
--  PostgreSQL compatibility mode, so the same migration can be verified by the
--  test suite (MigrationScriptTest) rather than only against a live database.
--
--  Conventions:
--    * identity columns use GENERATED BY DEFAULT AS IDENTITY (not SERIAL), which
--      is standard SQL and behaves identically on both engines
--    * timestamps are TIMESTAMP WITH TIME ZONE, written in UTC
--    * ON DELETE CASCADE only for pure join tables; references to business data
--      use ON DELETE SET NULL so deleting a user never erases history
-- ============================================================================

-- ------------------------------------------------------------------- security

CREATE TABLE permissions (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(100) NOT NULL,
    name        VARCHAR(150) NOT NULL,
    description VARCHAR(500),
    module      VARCHAR(50)  NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_permissions_code UNIQUE (code)
);

CREATE TABLE roles (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(50)  NOT NULL,
    name        VARCHAR(100) NOT NULL,
    description VARCHAR(500),
    system_role BOOLEAN      NOT NULL DEFAULT FALSE,
    active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_roles_code UNIQUE (code)
);

CREATE TABLE role_permissions (
    role_id       BIGINT NOT NULL,
    permission_id BIGINT NOT NULL,
    PRIMARY KEY (role_id, permission_id),
    CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE CASCADE,
    CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id) REFERENCES permissions (id) ON DELETE CASCADE
);

CREATE INDEX idx_role_permissions_permission ON role_permissions (permission_id);

-- -------------------------------------------------------------- organisation

CREATE TABLE organizations (
    id                  BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                VARCHAR(200) NOT NULL,
    legal_name          VARCHAR(200),
    registration_number VARCHAR(100),
    tax_id              VARCHAR(100),
    email               VARCHAR(255),
    phone               VARCHAR(50),
    website             VARCHAR(255),
    logo_url            VARCHAR(500),
    address_line1       VARCHAR(255),
    address_line2       VARCHAR(255),
    city                VARCHAR(100),
    state               VARCHAR(100),
    postal_code         VARCHAR(30),
    country             VARCHAR(100),
    timezone            VARCHAR(64),
    currency            VARCHAR(10),
    date_format         VARCHAR(32),
    created_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE TABLE departments (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(50)  NOT NULL,
    name        VARCHAR(150) NOT NULL,
    description VARCHAR(500),
    parent_id   BIGINT,
    -- Plain id, not a foreign key: see the note where the users table is created.
    manager_id  BIGINT,
    active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_departments_code UNIQUE (code),
    CONSTRAINT fk_departments_parent FOREIGN KEY (parent_id) REFERENCES departments (id) ON DELETE SET NULL
);


-- users.department_id and departments.manager_id reference each other. The
-- manager reference is kept as an indexed plain column rather than a foreign key:
-- that matches the Department entity (where managerId is a plain Long, not a
-- @ManyToOne) and avoids a circular FK between two tables that reference each
-- other, which would force an ALTER TABLE after the fact.
CREATE TABLE users (
    id                    BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username              VARCHAR(100) NOT NULL,
    email                 VARCHAR(255) NOT NULL,
    password              VARCHAR(255) NOT NULL,
    first_name            VARCHAR(100) NOT NULL,
    last_name             VARCHAR(100) NOT NULL,
    phone                 VARCHAR(50),
    job_title             VARCHAR(150),
    avatar_url            VARCHAR(500),
    status                VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    department_id         BIGINT,
    must_change_password  BOOLEAN      NOT NULL DEFAULT FALSE,
    failed_login_attempts INTEGER      NOT NULL DEFAULT 0,
    locked_until          TIMESTAMP,
    last_login_at         TIMESTAMP WITH TIME ZONE,
    password_changed_at   TIMESTAMP WITH TIME ZONE,
    created_at            TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at            TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by            BIGINT,
    updated_by            BIGINT,
    CONSTRAINT uq_users_username UNIQUE (username),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT fk_users_department FOREIGN KEY (department_id) REFERENCES departments (id) ON DELETE SET NULL,
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

CREATE TABLE user_roles (
    user_id BIGINT NOT NULL,
    role_id BIGINT NOT NULL,
    PRIMARY KEY (user_id, role_id),
    CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE CASCADE
);

CREATE INDEX idx_user_roles_role ON user_roles (role_id);
CREATE INDEX idx_users_department ON users (department_id);
CREATE INDEX idx_users_status ON users (status);

-- Index only: see the note on the departments table above.
CREATE INDEX idx_departments_manager ON departments (manager_id);

CREATE TABLE refresh_tokens (
    id         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash VARCHAR(64)  NOT NULL,
    user_id    BIGINT       NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked    BOOLEAN      NOT NULL DEFAULT FALSE,
    revoked_at TIMESTAMP WITH TIME ZONE,
    user_agent VARCHAR(300),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by BIGINT,
    updated_by BIGINT,
    CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id, revoked);

CREATE TABLE password_reset_tokens (
    id         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash VARCHAR(64)  NOT NULL,
    user_id    BIGINT       NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    used       BOOLEAN      NOT NULL DEFAULT FALSE,
    used_at    TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by BIGINT,
    updated_by BIGINT,
    CONSTRAINT uq_password_reset_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_password_reset_tokens_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);


-- --------------------------------------------------------------------- audit

CREATE TABLE audit_logs (
    id             BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT,
    username       VARCHAR(255),
    action         VARCHAR(50)  NOT NULL,
    module         VARCHAR(50)  NOT NULL,
    entity_type    VARCHAR(50),
    entity_id      VARCHAR(64),
    description    VARCHAR(500),
    previous_value VARCHAR(4000),
    new_value      VARCHAR(4000),
    ip_address     VARCHAR(64),
    user_agent     VARCHAR(300),
    success        BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE INDEX idx_audit_logs_user ON audit_logs (user_id);
CREATE INDEX idx_audit_logs_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX idx_audit_logs_created ON audit_logs (created_at);
CREATE INDEX idx_audit_logs_module_action ON audit_logs (module, action);

-- ------------------------------------------------------- settings & master data

CREATE TABLE system_settings (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    setting_key   VARCHAR(100) NOT NULL,
    setting_value VARCHAR(2000),
    value_type    VARCHAR(20)  NOT NULL DEFAULT 'STRING',
    setting_group VARCHAR(50)  NOT NULL DEFAULT 'GENERAL',
    description   VARCHAR(500),
    editable      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by    BIGINT,
    updated_by    BIGINT,
    CONSTRAINT uq_system_settings_key UNIQUE (setting_key)
);

CREATE TABLE master_data_items (
    id             BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_group     VARCHAR(50)  NOT NULL,
    code           VARCHAR(50)  NOT NULL,
    label          VARCHAR(150) NOT NULL,
    description    VARCHAR(500),
    sort_order     INTEGER      NOT NULL DEFAULT 0,
    active         BOOLEAN      NOT NULL DEFAULT TRUE,
    system_managed BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     BIGINT,
    updated_by     BIGINT
);

CREATE UNIQUE INDEX idx_master_data_group ON master_data_items (data_group, code);

-- --------------------------------------------------------------------- tasks

CREATE TABLE tasks (
    id                     BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reference              VARCHAR(32),
    title                  VARCHAR(250) NOT NULL,
    description            VARCHAR(4000),
    assigned_to_id         BIGINT,
    assigned_department_id BIGINT,
    priority               VARCHAR(20)  NOT NULL DEFAULT 'MEDIUM',
    status                 VARCHAR(20)  NOT NULL DEFAULT 'TODO',
    due_date               DATE,
    started_at             TIMESTAMP WITH TIME ZONE,
    completed_at           TIMESTAMP WITH TIME ZONE,
    estimated_hours        INTEGER,
    actual_hours           INTEGER,
    version                BIGINT,
    created_at             TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at             TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by             BIGINT,
    updated_by             BIGINT,
    CONSTRAINT uq_tasks_reference UNIQUE (reference),
    CONSTRAINT fk_tasks_assignee FOREIGN KEY (assigned_to_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_tasks_department FOREIGN KEY (assigned_department_id) REFERENCES departments (id) ON DELETE SET NULL,
    CONSTRAINT ck_tasks_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT')),
    CONSTRAINT ck_tasks_status CHECK (status IN ('TODO', 'IN_PROGRESS', 'ON_HOLD', 'COMPLETED', 'CANCELLED'))
);

CREATE INDEX idx_tasks_status ON tasks (status);
CREATE INDEX idx_tasks_assignee ON tasks (assigned_to_id);
CREATE INDEX idx_tasks_due_date ON tasks (due_date);

-- ----------------------------------------------------------------- documents

CREATE TABLE documents (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    filename      VARCHAR(255) NOT NULL,
    storage_key   VARCHAR(500) NOT NULL,
    content_type  VARCHAR(150) NOT NULL,
    size_bytes    BIGINT       NOT NULL,
    category      VARCHAR(50),
    description   VARCHAR(1000),
    uploaded_by_id BIGINT,
    version       INTEGER      NOT NULL DEFAULT 1,
    active        BOOLEAN      NOT NULL DEFAULT TRUE,
    row_version   BIGINT,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by    BIGINT,
    updated_by    BIGINT,
    CONSTRAINT uq_documents_storage_key UNIQUE (storage_key),
    CONSTRAINT fk_documents_uploader FOREIGN KEY (uploaded_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX idx_documents_category ON documents (category);
CREATE INDEX idx_documents_uploader ON documents (uploaded_by_id);

CREATE TABLE document_links (
    id           BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_id  BIGINT      NOT NULL,
    entity_type  VARCHAR(50) NOT NULL,
    entity_id    BIGINT      NOT NULL,
    linked_by_id BIGINT,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_document_links_document FOREIGN KEY (document_id) REFERENCES documents (id) ON DELETE CASCADE,
    CONSTRAINT fk_document_links_linked_by FOREIGN KEY (linked_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX idx_document_links_target ON document_links (entity_type, entity_id);
CREATE INDEX idx_document_links_document ON document_links (document_id);

-- ------------------------------------------------------------------ comments

CREATE TABLE comments (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entity_type VARCHAR(50)  NOT NULL,
    entity_id   BIGINT       NOT NULL,
    body        VARCHAR(4000) NOT NULL,
    author_id   BIGINT       NOT NULL,
    internal    BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_comments_author FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_comments_target ON comments (entity_type, entity_id);
CREATE INDEX idx_comments_author ON comments (author_id);

-- ---------------------------------------------------------- workflow engine

CREATE TABLE workflow_definitions (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(50)  NOT NULL,
    name        VARCHAR(150) NOT NULL,
    description VARCHAR(1000),
    active      BOOLEAN      NOT NULL DEFAULT TRUE,
    version     INTEGER      NOT NULL DEFAULT 1,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by  BIGINT,
    updated_by  BIGINT,
    CONSTRAINT uq_workflow_definitions_code UNIQUE (code)
);

CREATE TABLE workflow_step_definitions (
    id                BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    definition_id     BIGINT       NOT NULL,
    name              VARCHAR(150) NOT NULL,
    step_type         VARCHAR(20)  NOT NULL DEFAULT 'APPROVAL',
    step_order        INTEGER      NOT NULL,
    assignee_role_id  BIGINT,
    allow_rejection   BOOLEAN      NOT NULL DEFAULT TRUE,
    instructions      VARCHAR(1000),
    created_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by        BIGINT,
    updated_by        BIGINT,
    CONSTRAINT fk_workflow_step_definitions_definition FOREIGN KEY (definition_id) REFERENCES workflow_definitions (id) ON DELETE CASCADE,
    CONSTRAINT fk_workflow_step_definitions_role FOREIGN KEY (assignee_role_id) REFERENCES roles (id) ON DELETE SET NULL,
    CONSTRAINT ck_workflow_step_definitions_type CHECK (step_type IN ('APPROVAL', 'TASK', 'NOTIFICATION', 'SCRIPT'))
);


CREATE INDEX idx_workflow_step_definitions_definition ON workflow_step_definitions (definition_id, step_order);

CREATE TABLE workflow_instances (
    id                  BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reference           VARCHAR(32),
    definition_id       BIGINT       NOT NULL,
    definition_version  INTEGER      NOT NULL,
    title               VARCHAR(250) NOT NULL,
    description         VARCHAR(4000),
    status              VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    requester_id        BIGINT,
    current_assignee_id BIGINT,
    current_step_index  INTEGER      NOT NULL DEFAULT -1,
    submitted_at        TIMESTAMP WITH TIME ZONE,
    completed_at        TIMESTAMP WITH TIME ZONE,
    payload             VARCHAR(4000),
    row_version         BIGINT,
    created_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by          BIGINT,
    updated_by          BIGINT,
    CONSTRAINT uq_workflow_instances_reference UNIQUE (reference),
    CONSTRAINT fk_workflow_instances_definition FOREIGN KEY (definition_id) REFERENCES workflow_definitions (id) ON DELETE RESTRICT,
    CONSTRAINT fk_workflow_instances_requester FOREIGN KEY (requester_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_workflow_instances_assignee FOREIGN KEY (current_assignee_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_workflow_instances_status CHECK (
        status IN ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'COMPLETED', 'CANCELLED'))
);

CREATE INDEX idx_workflow_instances_status ON workflow_instances (status);
CREATE INDEX idx_workflow_instances_requester ON workflow_instances (requester_id);
CREATE INDEX idx_workflow_instances_assignee ON workflow_instances (current_assignee_id);
CREATE INDEX idx_workflow_instances_definition ON workflow_instances (definition_id);

CREATE TABLE workflow_instance_steps (
    id               BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instance_id      BIGINT       NOT NULL,
    step_name        VARCHAR(150) NOT NULL,
    step_type        VARCHAR(20)  NOT NULL DEFAULT 'APPROVAL',
    step_order       INTEGER      NOT NULL,
    status           VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    assignee_id      BIGINT,
    assignee_role_id BIGINT,
    decision_comment VARCHAR(2000),
    started_at       TIMESTAMP WITH TIME ZONE,
    completed_at     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_workflow_instance_steps_instance FOREIGN KEY (instance_id) REFERENCES workflow_instances (id) ON DELETE CASCADE,
    CONSTRAINT fk_workflow_instance_steps_assignee FOREIGN KEY (assignee_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_workflow_instance_steps_role FOREIGN KEY (assignee_role_id) REFERENCES roles (id) ON DELETE SET NULL,
    CONSTRAINT ck_workflow_instance_steps_status CHECK (
        status IN ('PENDING', 'IN_PROGRESS', 'APPROVED', 'REJECTED', 'SKIPPED'))
);

CREATE INDEX idx_workflow_instance_steps_instance ON workflow_instance_steps (instance_id, step_order);

-- ----------------------------------------------------------------- approvals

CREATE TABLE approvals (
    id                 BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reference          VARCHAR(32),
    title              VARCHAR(250) NOT NULL,
    description        VARCHAR(4000),
    status             VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    requester_id       BIGINT,
    amount             NUMERIC(19, 2),
    currency           VARCHAR(10),
    category           VARCHAR(50),
    source_entity_type VARCHAR(50),
    source_entity_id   BIGINT,
    submitted_at       TIMESTAMP WITH TIME ZONE,
    completed_at       TIMESTAMP WITH TIME ZONE,
    current_step_index INTEGER      NOT NULL DEFAULT -1,
    row_version        BIGINT,
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by         BIGINT,
    updated_by         BIGINT,
    CONSTRAINT uq_approvals_reference UNIQUE (reference),
    CONSTRAINT fk_approvals_requester FOREIGN KEY (requester_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_approvals_status CHECK (
        status IN ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'CANCELLED'))
);

CREATE INDEX idx_approvals_status ON approvals (status);
CREATE INDEX idx_approvals_requester ON approvals (requester_id);
CREATE INDEX idx_approvals_category ON approvals (category);

CREATE TABLE approval_steps (
    id               BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id      BIGINT       NOT NULL,
    name             VARCHAR(150) NOT NULL,
    step_order       INTEGER      NOT NULL,
    status           VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    approver_id      BIGINT,
    approver_role_id BIGINT,
    comment          VARCHAR(2000),
    decided_at       TIMESTAMP WITH TIME ZONE,
    decided_by_id    BIGINT,
    CONSTRAINT fk_approval_steps_approval FOREIGN KEY (approval_id) REFERENCES approvals (id) ON DELETE CASCADE,
    CONSTRAINT fk_approval_steps_approver FOREIGN KEY (approver_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_approval_steps_role FOREIGN KEY (approver_role_id) REFERENCES roles (id) ON DELETE SET NULL,
    CONSTRAINT ck_approval_steps_status CHECK (
        status IN ('PENDING', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'SKIPPED'))
);

CREATE INDEX idx_approval_steps_approval ON approval_steps (approval_id, step_order);
CREATE INDEX idx_approval_steps_approver ON approval_steps (approver_id, status);

CREATE TABLE approval_actions (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    approval_id BIGINT       NOT NULL,
    step_id     BIGINT,
    actor_id    BIGINT,
    action      VARCHAR(30)  NOT NULL,
    comment     VARCHAR(2000),
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_approval_actions_approval FOREIGN KEY (approval_id) REFERENCES approvals (id) ON DELETE CASCADE,
    CONSTRAINT fk_approval_actions_step FOREIGN KEY (step_id) REFERENCES approval_steps (id) ON DELETE SET NULL,
    CONSTRAINT fk_approval_actions_actor FOREIGN KEY (actor_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX idx_workflow_instance_steps_assignee ON workflow_instance_steps (assignee_id, status);

-- ------------------------------------------------------------- notifications

CREATE TABLE notifications (
    id         BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT       NOT NULL,
    type       VARCHAR(50)  NOT NULL,
    title      VARCHAR(250) NOT NULL,
    message    VARCHAR(1000),
    link_url   VARCHAR(500),
    read       BOOLEAN      NOT NULL DEFAULT FALSE,
    read_at    TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_notifications_user_unread ON notifications (user_id, read);
CREATE INDEX idx_notifications_created ON notifications (created_at);

CREATE TABLE notification_preferences (
    id                BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id           BIGINT      NOT NULL,
    notification_type VARCHAR(50) NOT NULL,
    in_app_enabled    BOOLEAN     NOT NULL DEFAULT TRUE,
    email_enabled     BOOLEAN     NOT NULL DEFAULT FALSE,
    sms_enabled       BOOLEAN     NOT NULL DEFAULT FALSE,
    push_enabled      BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_notification_preferences_user_type UNIQUE (user_id, notification_type),
    CONSTRAINT fk_notification_preferences_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
